// src/pages/LoginRequiredPage.tsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function LoginRequiredPage() {
  const nav = useNavigate();
  const [q, setQ] = useState("");

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!q.trim()) return;
    nav(`/search?q=${encodeURIComponent(q.trim())}`);
  };

  return (
    <div className="min-h-screen bg-gray-100 grid place-items-start"> {/* bg-grey → bg-gray-100 예시 */}
      <div className="mx-auto h-full w-full max-w-[480px]">
        {/* 검색 인풋 */}
        <main className="relative px-6 pt-7 pb-5">
          <form onSubmit={onSubmit}>
            <label htmlFor="q" className="sr-only">검색어</label>
            <input
              id="q"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="검색하세요"
              autoComplete="off"
              autoFocus
              className="
                block w-full
                text-[24px]
                placeholder:text-gray-400
                outline-none
                border-0
                border-b border-gray-400
                pb-2               /* pb- → pb-2 */
                pr-12              /* 아이콘 공간 확보 */
                focus:border-black
                transition
              "
              aria-label="검색어 입력"
            />
            {/* 돋보기 버튼: 우측 중앙 정렬 */}
            <button
              type="submit"
              aria-label="검색"
              className="absolute right-6 top-1/2 -translate-y-1/2 h-10 w-10 grid place-items-center rounded-full hover:bg-black/5 active:scale-95 transition"
            >
              <svg width="22" height="22" viewBox="0 0 24 24" stroke="currentColor" fill="none">
                <circle cx="11" cy="11" r="7" strokeWidth="2" />
                <path d="M20 20l-3-3" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          </form>
        </main>
      </div>
    </div>
  );
}
